/**
 * Environment Resolution Module
 *
 * Handles resolution of the runtime environment (preview vs production)
 * and validates release ID requirements.
 *
 * @module server/runtime-handler/environment-resolution
 */
import { getBaseLogger } from "../../utils/index.js";
import { ErrorPages } from "../utils/error-html.js";
const baseLogger = getBaseLogger("SERVER");
const logger = baseLogger.component("environment-resolution");
/**
 * Resolve the runtime environment and validate release ID requirements.
 *
 * Returns an error response if validation fails (e.g., missing releaseId in production).
 */
export function resolveEnvironment(opts) {
    let resolvedEnvironment = opts.proxyEnv === "preview" || opts.proxyEnv === "production" ? opts.proxyEnv : opts.reqCtxMode;
    let releaseId = opts.releaseId;
    // Some framework control-plane surfaces are routed directly to a runtime owner pod and
    // rely on signed control-plane auth instead of a user-facing release address.
    const isControlPlanePath = opts.pathname.startsWith("/api/control-plane/");
    // Skip releaseId validation for development assets and signed control-plane
    // requests because they do not require a user-facing release context. Module
    // transports are deliberately excluded: both the canonical and legacy paths
    // can resolve tenant source, so hosted production requests must carry an
    // immutable release identity before they reach the module server.
    const isBrowserModulePath = opts.pathname.startsWith("/_vf_modules/") ||
        opts.pathname.startsWith("/_veryfront/modules/");
    const canSkipReleaseIdValidation = opts.pathname === "/_ws" ||
        (opts.pathname.startsWith("/_veryfront/") && !isBrowserModulePath) ||
        isControlPlanePath;
    // Validate releaseId in proxy mode production
    if (opts.isProxyMode &&
        resolvedEnvironment === "production" &&
        opts.projectSlug &&
        !releaseId &&
        !opts.isLocalProject &&
        !canSkipReleaseIdValidation) {
        logger.warn("No active release found (proxy mode)", {
            projectSlug: opts.projectSlug,
            projectId: opts.projectId,
            environmentName: opts.environmentName,
            host: opts.host,
            proxyEnv: opts.proxyEnv,
            resolvedEnvironment,
        });
        return {
            resolvedEnvironment,
            releaseId,
            errorResponse: new Response(ErrorPages.notFound(), {
                status: 404,
                headers: { "Content-Type": "text/html; charset=utf-8" },
            }),
        };
    }
    // Handle standalone mode without release ID
    const isStandaloneWithoutRelease = !opts.isProxyMode &&
        resolvedEnvironment === "production" &&
        !releaseId &&
        !opts.isLocalProject;
    if (isStandaloneWithoutRelease) {
        const fallbackEnv = opts.defaultEnvironment ?? "preview";
        logger.debug("[environment-resolution] Standalone mode without releaseId, using fallback environment", {
            projectSlug: opts.projectSlug,
            resolvedEnvironment,
            fallbackEnv,
        });
        resolvedEnvironment = fallbackEnv;
        if (fallbackEnv === "production" && !releaseId) {
            releaseId = "standalone-dev";
            logger.debug("[environment-resolution] Using synthetic releaseId for standalone production mode", {
                projectSlug: opts.projectSlug,
                releaseId,
            });
        }
    }
    return {
        resolvedEnvironment,
        releaseId,
        errorResponse: undefined,
    };
}
